import{f as n,c as t,o as s,aq as r}from"./chunks/framework.D9EfIZ-r.js";const f=JSON.parse('{"title":"Testkonzept","description":"","frontmatter":{},"headers":[],"relativePath":"technik/testconcepts/index.md","filePath":"technik/testconcepts/index.md"}'),i={name:"technik/testconcepts/index.md"};function a(d,e,u,o,l,c){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="testkonzept" tabindex="-1">Testkonzept <a class="header-anchor" href="#testkonzept" aria-label="Permalink to &quot;Testkonzept&quot;">​</a></h1><p>Auf den Seiten zum <a href="./backend.html">Backend</a> und Frontend werden die jeweiligen Testkonzepte beschrieben.</p><p>Für den Aufbau und die Benennung von Tests sind die <a href="./../naming_conventions/">Namingkonventions</a> zu beachten.</p><p>Unabhängig von Backend und Frontend gibt es weitere manuelle Teststufen.</p><h2 id="manuelle-teststufen" tabindex="-1">Manuelle Teststufen <a class="header-anchor" href="#manuelle-teststufen" aria-label="Permalink to &quot;Manuelle Teststufen&quot;">​</a></h2><h3 id="code-review" tabindex="-1">Code-Review <a class="header-anchor" href="#code-review" aria-label="Permalink to &quot;Code-Review&quot;">​</a></h3><p>Ziel: Überprüfung der Code-Qualität und der korrekten Umsetzung der Anforderungen, sowie die Einhaltung von Projektvorgaben.</p><p>Was: Jeder Pull-Request, der auf den Default-Branch geht, muss gereviewt werden. Pull-Requests mit einem anderen Ziel können optional einem Review unterzogen werden.</p><p>Wie: Die Workflows stellen eine syntaktische Funktionsfähigkeit der Anwendung fest, sowie die Einhaltung eines definierten Stils. Reviewer prüfen die Einhaltung der Definition of Done, sowie eine korrekte, vollständige und effiziente Umsetzung. In der Regel muss für das Review der Code lokal ausgecheckt werden. Feedback ist im Pull-Request zu geben.</p><p>Verantwortung: Entwicklungsteam</p><p>Ausführung: Der Ersteller eines Pull-Requests trägt die Verantwortung, dass ein Review durchgeführt wird. Entwickler aus dem Entwicklungsteam weisen sich selbständig PRs für ein Review zu.</p><h3 id="sprint-review" tabindex="-1">Sprint-Review <a class="header-anchor" href="#sprint-review" aria-label="Permalink to &quot;Sprint-Review&quot;">​</a></h3><p>Ziel: Überprüfung, ob die Anforderungen, die in einem Issue gestellt wurden, fachlich korrekt umgesetzt wurden.</p><p>Was: Jedes Issue, dass eine für den Fachbereich relevante Änderung hatte.</p><p>Wie: Vorstellung des Ergebnisses im Rahmen der Demo. In Vorbereitung auf die Demo wird geklärt, durch wen die Vorstellung erfolgt.</p><p>Verantwortung: Entwicklungsteam</p><p>Ausführung: Am Ende jedes Sprints auf der Umgebung für die Demo.</p><h2 id="bedarfsgesteuerte-tests" tabindex="-1">Bedarfsgesteuerte Tests <a class="header-anchor" href="#bedarfsgesteuerte-tests" aria-label="Permalink to &quot;Bedarfsgesteuerte Tests&quot;">​</a></h2><p>Zusätzlich zu den beschriebenen Tests werden je nach Bedarf folgende weitere Tests durchgeführt:</p><ul><li>Systemtests, technisch und fachlich</li><li>Last und Performancetests</li><li>Pentests</li></ul>',20)])])}const p=n(i,[["render",a]]);export{f as __pageData,p as default};
